// Package headers embeds the C headers a cell can include: wasi-libc's for
// wasm32-wasip1 and the target-independent part of clang's resource
// directory, both at the oracle's pinned revisions (clang 23.1.4, wasi-libc
// d9ad2d11991c). Embedding them is what lets the front end run where there is
// no file system at all, the wasm playground.
//
// The tree is generated by internal/cmd/genheaders from the oracle
// toolchain; licences are include/LICENSE-llvm.txt and
// include/wasi-libc-LICENSE*.
package headers

import (
	"embed"
	"io/fs"
)

//go:embed all:include
var tree embed.FS

// Search directories, in clang's order for wasm32-wasip1: the resource
// headers first (their stdint.h and inttypes.h #include_next libc's), then
// libc's.
const (
	ClangDir = "include/clang"
	WasiDir  = "include/wasi"
)

// SysIncludePaths is the #include <…> search path inside FS.
var SysIncludePaths = []string{ClangDir, WasiDir}

// FS returns the embedded tree.
func FS() fs.FS { return tree }
